/**
 * Generates Open/Close Fields for variables under functions.
 */
public class FunctionOpenCloseFieldFactory : FieldFactory {

	public static readonly string FIELD_NAME = "+";

	public FunctionOpenCloseFieldFactory() : base(FIELD_NAME)
    {
	}

	/**
	 * Constructor
	 * @param model the model that the field belongs to.
	 * @param hlProvider the HightLightStringProvider.
	 * @param displayOptions the Options for display properties.
	 * @param fieldOptions the Options for field specific properties.
	 */
	private FunctionOpenCloseFieldFactory(FieldFormatModel model,
			ListingHighlightProvider hlProvider,
			Options displayOptions, Options fieldOptions) : base(FIELD_NAME, model, hlProvider, displayOptions, fieldOptions)
    {
		servicesChanged();
	}

	/**
	 * Returns the FactoryField for the given object at index index.
	 * @param varWidth the amount of variable width spacing for any fields
	 * before this one.
	 * @param proxy the object whose properties should be displayed.
	 */
	/* @Override */
	public ListingField getField(ProxyObj<object> proxy, int varWidth) {
		if (!enabled) {
			return null;
		}
		if (proxy is FunctionProxy) {
			return new FunctionOpenCloseField(this, proxy, getMetrics(), startX + varWidth, width);
		}
		return null;
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int row, int col, ListingField bf) {
